static int cuse_dev_release(struct inode *inode, struct file *file)
{
    struct fuse_conn *conn = fuse_get_conn(inode);
    int res;

    mutex_lock(&fuse_mutex);
    list_del(&conn->entry);
    mutex_unlock(&fuse_mutex);

    if (conn->cdev) {
        unregister_chrdev_region(conn->cdev, 1);
        cdev_del(conn->cdev);
    }

    res = fuse_dev_release(inode, file);
    fuse_put_conn(conn);

    return res;
}

int cuse_channel_release(struct inode *inode, struct file *file)
{
    struct fuse_conn *fc = file->private_data;
    int res;

    mutex_lock(&fc->lock);
    list_del(&fc->entry);
    mutex_unlock(&fc->lock);

    if (fc->dev)
        unregister_chrdev_region(fc->dev, 1);

    cdev_del(&fc->cdev);
    fc->connected = false;

    res = fuse_dev_release(inode, file);
    fuse_put_conn(fc);
    return res;
}

#include <linux/mutex.h>
#include <linux/fs.h>
#include <linux/err.h>

int cuse_channel_release(struct inode *inode, struct file *file) {
    struct fuse_conn *conn = fuse_get_conn(inode);
    int res;

    mutex_lock(&conn->lock);
    if (conn->dev) {
        unregister_chrdev_region(conn->dev, 1);
        conn->dev = NULL;
    }
    list_del(&conn->entry);
    mutex_unlock(&conn->lock);

    res = fuse_dev_release(inode, file);
    fuse_put_conn(conn);
    return res;
}

static int cuse_channel_release(struct inode *inode, struct file *file)
{
    struct fuse_conn *fc = file->private_data;
    int res;

    mutex_lock(&fc->lock);
    list_del(&fc->entry);
    mutex_unlock(&fc->lock);

    if (fc->dev)
        device_destroy(fc->class, fc->dev);

    cdev_del(&fc->cdev);
    put_device(&fc->dev);

    res = fuse_dev_release(inode, file);
    return res;
}

#include <linux/mutex.h>
#include <linux/cdev.h>
#include <linux/device.h>

int cuse_channel_release(struct inode *inode, struct file *file)
{
    struct fuse_conn *fc = fuse_get_conn(inode);
    int res;

    mutex_lock(&fc->lock);
    list_del(&fc->entry);
    mutex_unlock(&fc->lock);

    if (fc->dev) {
        device_unregister(fc->dev);
        fc->dev = NULL;
    }

    cdev_del(&fc->cdev);
    fc->release(fc);

    res = fuse_dev_release(inode, file);
    return res;
}
